using System.Collections.Generic;
using UnityEngine;

namespace Zcom
{
    /// <summary>
    /// Loads the Blender-made character models (Resources/Models/*.fbx, generated by Tools/Blender/zcom_characters.py)
    /// and swaps their Blender materials for the game's URP materials by name.
    /// </summary>
    public static class CharacterModels
    {
        /// <summary>Instantiates a model under parent. Returns null when the FBX is missing (callers fall back to primitives).</summary>
        public static GameObject Spawn(string name, Transform parent, IDictionary<string, Material> materials)
        {
            var prefab = Resources.Load<GameObject>("Models/" + name);
            if (!prefab) return null;
            var go = Object.Instantiate(prefab, parent, false);
            go.name = name + "Model";
            go.transform.localPosition = Vector3.zero;
            go.transform.localRotation = Quaternion.identity;

            // Safety net: models are authored facing +Z ("Front" marker); flip if an export ever comes in backwards.
            var front = Find(go.transform, "Front");
            if (front && front.localPosition.z < 0f) go.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);

            foreach (var r in go.GetComponentsInChildren<Renderer>(true))
            {
                var mats = r.sharedMaterials;
                for (int i = 0; i < mats.Length; i++)
                {
                    if (!mats[i]) continue;
                    string key = mats[i].name.Replace(" (Instance)", "");
                    if (materials != null && materials.TryGetValue(key, out var m) && m) mats[i] = m;
                }
                r.sharedMaterials = mats;
                r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On;
            }
            return go;
        }

        public static Transform Find(Transform root, string name)
        {
            if (root.name == name) return root;
            foreach (Transform c in root)
            {
                var f = Find(c, name);
                if (f) return f;
            }
            return null;
        }

        /// <summary>Children whose names start with prefix, sorted by name (Leg_0, Leg_1, ...).</summary>
        public static Transform[] FindAll(Transform root, string prefix)
        {
            var list = new List<Transform>();
            foreach (var t in root.GetComponentsInChildren<Transform>(true))
                if (t.name.StartsWith(prefix)) list.Add(t);
            list.Sort((a, b) => string.CompareOrdinal(a.name, b.name));
            return list.ToArray();
        }
    }
}
